def summarize(rows):
    """rows: list of dicts with 'category' and 'amount' strings. Return {category: total}."""
    totals = {}
    for row in rows:
        # Normalize category: strip whitespace and convert to lowercase
        category = row["category"].strip().lower()

        # Skip rows with empty category
        if not category:
            continue

        # Strip whitespace from amount
        amount_str = row["amount"].strip()

        # Skip rows with empty amount
        if not amount_str:
            continue

        # Try to convert amount to float, skip if it's not a valid number
        try:
            amount = float(amount_str)
        except (ValueError, TypeError):
            continue

        # Accumulate totals
        if category in totals:
            totals[category] += amount
        else:
            totals[category] = amount

    # Round each total to 2 decimal places
    for category in totals:
        totals[category] = round(totals[category], 2)

    return totals
